"""Stop-lists for the Komi game (Yandex Games rule 3.4.5: no references to religion; plus profanity / adult / death).
Used by lexicon.py / build_game.py to keep such words out of crosswords, daily puzzles, bonus words, word of the day and cards."""
import re
# Komi religious vocabulary (Christianity, mythology/afterlife). Exact words; stems are in the stem regex below.
STOP_WORDS = {   # Komi religious / mythological vocabulary
    'ен', 'енлӧн', 'енмӧ', 'енъяс', 'енбиа', 'вичко', 'вичкоын', 'вичкоӧ', 'вежа', 'вежавидз', 'вежавидзны', 'юрбитны', 'юрбитӧм', 'юрбитчысь', 'юрбитан',
    'крест', 'крёст', 'поп', 'попъяс', 'дьяк', 'монах', 'икона', 'енколаст', 'ичмоньяс', 'кулӧм', 'кулӧмъяс', 'гу', 'гуъяс', 'шыпича', 'ворса',
    'васа', 'тӧдысь', 'тун', 'туна', 'пелысь', 'куль', 'кульлӧн', 'йӧла', 'бес', 'бесъяс', 'чудь', 'пера', 'енмӧй', 'збыльвыв',
    'рай', 'ад', 'шайтан', 'сатана', 'ангел', 'христос', 'пасха', 'рӧштво', 'вежалун', 'гуалан', 'гуасянін',
}
STOP_RE = re.compile(r'^(?:вичко|енм|юрбит|вежа(?:н|л|д)|попъя|кулӧм|гуал|алла(?!н|р)|ходай|тәңре|мәчет|мулла|намаз|ураза|коръән|пәйгамбәр|ислам|мөселман|дин(?:и|ле|сез|дар)|иман|кя?фер|гөнаһ|шә?[ая]йтан|'
                     r'фәрештә|оҗмах|тәмуг|җәһәннәм|ахирәт|дога|зикер|хаҗ(?:и|ия)?$|мәдрәсә|хәзрәт|мөфти|сәдака|зәкят|корбан|кыямәт|сәҗдә|тәсбих|чиркәү|'
                     r'христиан|чукын|керәшен|икона|рамазан|шәри[гғ]ать|гыйбадәт|бәрәкәт|сихер|табын(?:у|учы|ыр|ды|а|ган)?$|күрәзә|әрвах|тәүбә|изге)')
# Russian clue patterns (word-boundary aware, so богатый / крестьянин / огрех / черта / культура don't match)
GLOSS_RE = re.compile(r'(?<![а-яё])(?:'
    r'бог(?:а|у|ом|е|и|ов|ам|ами|ах|иня|ини|ине|иню)?(?![а-яё])|бож(?:еств|ий|ья(?! коровк)|ье|ьи|ниц)|богородиц|богомол|аллах|всевышн|'
    r'жрец|жреч|молит|молен|молельщ|молеб|молельн|моления|намаз(?!ан|ыв|ать)|пророк|коран|ислам|мусульман|мечет|минарет|медресе|шариат|муэдзин|хадж|паломн|'
    r'церк|христ|ангел|дьявол|сатан|шайтан|джинн|демон|нечисть|нечист(?:ая|ой|ую) сил|злой дух|бес(?:а|ы|ов|ам)?(?![а-яё])|чёрт|'
    r'ад(?:а|у|ом)?(?![а-яё])|ра(?:й|я|ю|ем)(?![а-яё])|загробн|судный|воскрес(?:ени|л)|греш|грех|свят|священ|причащ|рождеств|икон|'
    r'крест(?!ьян|ов[кн]|оцвет|ц|ец|ообраз)|креще|жертвопринош|жертвовател|религ|вероучен|верующ|вероотступ|язычес|язычник|культ(?:а|ов|у|ом|е|овый|овое|овая)?(?![а-яё])|'
    r'храм|леш(?:ий|его|им)|водян(?:ой|ого)|домов(?:ой|ого|ых)|русалк|дух(?:а|и|ов)?(?![а-яё])|нечист|оберег|колокол|купол|часовн|собор|обитель|монах|монаш|мулл|имам|поп(?:а|у|ом|ы|ов)?(?![а-яё])|пасх|троиц|идол|шаман|колдов|колдун|ведьм|знахар|гадал|гадани|магии|магия|заклинан|'
    r'похорон|покойн|кладбищ|могил(?!ьник)|саван|поминк|мертвец|усопш|'
    r'пост(?:ить|иться)|разговлен|благословен|проклят|милостын|ниспослан|обет(?:а|ы)?(?![а-яё])|чудотвор|поклоня|поклонени|гада(?:ть|ю|ние)|предсказ|заговарив|призрак|привидени|предопредел|предначерт|(?<![а-яё])рок(?![а-яё])|обряд|ритуал|кябин'
    r')', re.I)

# profanity / adult / drugs / violence (Russian clue roots and Wiktionary labels) + a few Komi roots
BAD_RU = re.compile(r'(?<![а-яё])(?:хуй|хуе|хуё|пизд|ебат|ебан|ёб|бляд|блят|сука|суки|жоп|говн|дерьм|срат|ссат|мудак|мудил|пидор|педик|шлюх|гандон|залуп|'
                    r'дурак|дура(?![а-яё])|идиот|урод|дебил|кретин|негр(?!амот)|жид|нацист|фашист|наркот|героин|убий|убить|убива|труп|смерт|секс|порн|'
                    r'член(?: тела)?(?= мужск)|половой|половые|половых|испражн|кал(?![а-яё])|навоз|моча|мочи|мочиться|задниц|ягодиц|анус|задний проход|'
                    r'блуд|разврат|распут|проститут|любовни|изнасил|водк|самогон|пьян|алкогол|спиртн|вино(?![а-яё])|винн|пив(?:о|а)(?![а-яё])|окурок|сигарет|табак|опьян|самоубий|казн(?:ь|ить|и(?![а-яё]))|виселиц|палач|'
                    r'penis|vagina|vulgar|offensive|derogatory|feces|faeces|urine|sexual)', re.I)
BAD_LABELS = ('бран.', 'груб.', 'вульг.', 'неценз.', 'презр.', 'обсц.', 'мат.', 'религ.', 'мифол.', 'церк.', 'рел.', 'пренебр.')
BAD_TT = re.compile(r'^(?:кулӧм|кувны|кулі|вина|пиво|сур(?:а)?$|винаӧн|виявны)')

# English glosses (en.wiktionary bonus words)
EN_RE = re.compile(r'\b(?:god|gods|goddess|deity|church|chapel|cross|priest|monk|nun|saint|holy|sacred|pray|prayer|icon|heaven|hell|devil|demon|spirit|ghost|soul|'
                   r'testament|bible|gospel|christ|christian|pagan|shaman|witch|sorcer|magic|grave|funeral|burial|corpse|dead|death|stillborn|vault|'
                   r'semen|milt|vomit|pus|suppurat|feces|urine|sex|vodka|beer|wine)', re.I)

def religious(w, clue=''):
    w = w.lower()
    if w in STOP_WORDS or STOP_RE.match(w): return True
    return bool(clue and (GLOSS_RE.search(clue.lower()) or EN_RE.search(clue)))

def offensive(w, clue='', labels=''):
    if BAD_TT.match(w.lower()): return True
    if any(l in labels for l in BAD_LABELS): return True
    return bool(clue and (BAD_RU.search(clue.lower()) or re.search(r'рвот|нагноен|гно[йя]|понос|гнид|вош[ьи]|глист|сопл|пердеж|пук|отрыжк|моча|кал(?![а-яё])', clue.lower())))
